L000307	    \includegraphics[width=0.6\linewidth]{figures_SM/CriticalDriving-1D-2D-and_others.pdf}
L000308	    \caption{Evolution of the critical point $I_{\min}$ as a function of $\Delta$. A quadratic dependence is observed, consistent with estimates based on the single-mode mean-field description of the bistability curve. The inflection point of the mean-field curve (grey line) closely approximates the critical point across all geometries considered.}
L000309	
L000310	    \label{fig:I_min}
L000311	\end{figure}
